const o = { n: 1, inc() { this.n++; return this.n; }, pure() { return 7; } };
async function main(): Promise<void> {
  const g = o.pure;
  console.log(g());
  const f = o.inc;
  console.log("extracted", typeof f);
  try { f(); console.log("called"); } catch (e) { console.log("threw", (e as Error).name); }
  console.log(o.n, o.inc());
}
